export default [{"id":87,"question":"ما صفات السبعين ألفًا الذين يدخلون الجنة بغير حسابٍ؟","title":"ما صفات الذين يدخلون الجنة بغير حساب؟","answer":"الجواب: بيَّن النبيُّ ﷺ أنَّهم المُستقيمون على دين الله، فهم سبعون ألفًا، ومع كل ألفٍ سبعون ألفًا، وهم مقدّم هذه الأمة المؤمنة، يتقدَّمونهم في دخول الجنة على صورة القمر ليلة البدر، وهم الذين جاهدوا بأمر الله، واستقاموا على دين الله أينما كانوا، بأداء الفرائض، وترك المحارم، والمُسابقة إلى الخيرات.\nومن صفاتهم أنهم: لا يسترقون، ولا يكتوون، ولا يتطيَّرون.\nلا يسترقون أي: لا يطلبون مَن يرقيهم، ولا يكتوون، وليس معناه تحريم هذا، فلا بأس بطلب الرقية، ولا بأس بالكي عند الحاجة إليهما، ولكن من صفاتهم: ترك ذلك والاستغناء بالأسباب الأخرى.\nلا يسترقون أي: لا يطلبون مَن يرقيهم، أي: لا يقولون: يا فلان، ارقنا، وإذا دعت الحاجةُ فلا بأس، لا يُخرجه ذلك -إذا دعت الحاجةُ- عن السبعين.\nولهذا أمر النبيُّ ﷺ عائشة أن تسترقي في بعض مرضها، وأمر أمَّ أيتام جعفر بن أبي طالب أن تسترقي لهم، كما في الحديث الصَّحيح.\nوهكذا الكي، فقد كوى بعض أصحابه عليه الصلاة والسلام، وقال: الشفاء في ثلاثٍ: كيَّة نار، أو شرطة محجم، أو شربة عسل، وما أحبُّ أن أكتوي، وقال: أنهى أمتي عن الكي، فالكي آخر الطب، فإذا تيسر الطبُّ الآخر فهو أوْلى، وإذا دعت الحاجةُ إليه فلا بأس.\nس: إذا ذهب بأحدٍ يرقيه؟\nج: لا بأس، إذا دعت الحاجةُ إلى هذا فلا بأس، لكن تركه أفضل، فإذا تيسر له سببٌ آخر فهو أفضل، إن تيسر له أن يرقيه بدون سؤالٍ أو بسببٍ آخر من الأسباب التي تنفعه فلا بأس، وهو أحسن.","link":"https://binbaz.org.sa/fatwas/3089/ما-صفات-الذين-يدخلون-الجنة-بغير-حساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0064.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":258,"question":"علمنا أنَّ المرأة إن كانت صالحةً حُشرت مع زوجها يوم القيامة، وإن كان زوجُها من أهل النار -والعياذ بالله- أين تكون زوجته الصَّالحة؟ ومع مَن تُحشر؟","title":"هل تُحشر المرأة مع زوجها يوم القيامة؟","answer":"الجواب: الشيخ: قوله تعالى: احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ [الصافات:22]، ليس المراد به: الزوجات، فأزواجهم: أشباههم ونُظراؤهم في العمل السيئ، أو العمل الطيب.\nوهكذا قوله: وَإِذَا النُّفُوسُ زُوِّجَتْ [التكوير:7] يعني: زُوِّج كلُّ إنسانٍ بقرينه، ومن يعمل عمله.\nفقوله سبحانه: احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ ليس المراد: زوجاتهم، لا، المراد بأزواجهم: أشباههم ونُظراؤهم، فزيد وعمرو إذا تساوا فهو زوجه، سواء في العمل، فأزواجهم: نظراؤهم وأشباههم في عمل الخير والشرِّ، فهؤلاء الظالمون يُحشرون مع أشباههم في الشرك والفساد، كما يُحشر المؤمنون مع نُظرائهم إلى الجنة والسعادة.\nأما الزوج والزوجة فلهما أمرٌ آخر: إذا صلح الزوجُ والزوجةُ صارا جميعًا من أهل الجنة، أما كونها تتزوج عليه أو لا تتزوج عليه فهذا شيءٌ آخر الله أعلم به جلَّ وعلا، قد يكون لها أزواجٌ –المرأة- فليس من المُتحتم أن تكون مع فلانٍ أو فلانٍ.\nقد جاء في حديثٍ فيه ضعفٌ رواه الطبراني وجماعة: أن الزوجة تُخيّر إذا كان لها أزواجٌ، فتختار أحسنَهم خلقًا إذا دخلت الجنة، ولكن في سنده ضعفٌ ومقالٌ.\nفالمقصود أنها إذا كان لها أزواج فالله أعلم بمَن تكون له منهم، وكذلك إذا كان لها زوجٌ واحدٌ، الله أعلم: هل تكون معه في الجنة، أو تكون أعلى منه، أو يكون أعلى منها، أو تُزوّج بغيره؟ هذا إلى الله سبحانه، ليس عندنا نصٌّ واضحٌ في هذا المقام.","link":"https://binbaz.org.sa/fatwas/4251/هل-تحشر-المراة-مع-زوجها-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0302.mp3","categories":["اليوم الآخر"]},{"id":980,"question":"هل يرى المؤمنُ الله  قبل يوم القيامة وقبل دخوله الجنة؟ وما الدليل على ذلك؟","title":"هل يرى المؤمنُ ربه عزَّ وجل قبل القيامة؟","answer":"الجواب: يقول النبيُّ ﷺ: واعلموا أنَّ أحدكم لا يرى ربَّه حتى يموت، فالرب لا يراه أحدٌ في الدنيا، وإنما يُرى في الآخرة في موقف القيامة، وفي الجنة، يراه المؤمنُ في الموقف وفي الجنة، أما في الدنيا فلا يراه، حتى النبي ﷺ ما رأى ربَّه في الدنيا، قد يُرى في النوم، قد رآه النبيُّ في النوم، ورؤية النوم ممكنة على وجهٍ لا يُشابه خلقه : قد يسمع كلامًا، قد يرى نورًا، ولكن لا يراه على ما هو عليه إلا يوم القيامة، أو في الجنة.\nوالكفار لا يرونه: لا في القيامة، ولا في الآخرة كلها، قال تعالى: كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ [المطففين:15]، فالكفار لا يرونه أبدًا.\nوالمؤمنون يرونه يوم القيامة وفي الجنة، كما يشاء ، وذلك أعلى نعيمهم، كما قال : وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ  ۝  إِلَى رَبِّهَا نَاظِرَةٌ [القيامة:22- 23]، وقال سبحانه: عَلَى الْأَرَائِكِ يَنْظُرُونَ [المطففين:23] أي: إلى ربهم جلَّ وعلا، وقال سبحانه: لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ [يونس:26]، وقال النبيُّ ﷺ: الزيادة: النظر إلى وجه الله، وتواترت الأخبارُ عن رسول الله ﷺ أنه قال: إن المؤمنين يرون ربَّهم يوم القيامة عيانًا بأبصارهم، كما يرون الشمسَ صَحْوًا ليس دونها سحابٌ، وكما يرون القمر ليلة البدر، لا يُضامون في رؤيته.\nهذه عقيدة أهل السنة والجماعة، خلافًا للمُبتدعة.","link":"https://binbaz.org.sa/fatwas/21030/هل-يرى-المومن-ربه-عز-وجل-قبل-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0827هل يرى المؤمن الله عز وجل قبل يوم القيامة وقبل دخول الجنة؟ ابن باز فتاوى المحاضرات.mp3","categories":["اليوم الآخر"]},{"id":1108,"question":"هل الملائكة يرون الله ؟","title":"ما الحق في رؤية المؤمنين والملائكة ربهم؟","answer":"الجواب:\nلا أعرف، ما ورد في هذا شيءٌ عن الله، ولا عن الرسول ﷺ، ولا عن الله في الملائكة، جاء في الحديث الصحيح: أنَّ حجابه النور، لو كشفه لأحرقت سُبُحات وجهه ما انتهى إليه بصرُه من خلقه.\nولا أعلم في شيءٍ من النصوص ما يدل على أنَّ الملائكة ترى الله ، هذا يحتاج إلى دليلٍ من المعصوم عليه الصلاة والسلام في ذلك.  أما المؤمنون والمؤمنات فيرون الله يوم القيامة، وفي الجنة، المؤمنون والمؤمنات يرون الله سبحانه يوم القيامة، وفي الجنة، كما أخبر به النبيُّ ﷺ، وتواترت به الأحاديث عن رسول الله عليه الصلاة والسلام، وقال الله جلَّ وعلا: وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ  ۝  إِلَى رَبِّهَا نَاظِرَةٌ [القيامة:22- 23]، ومعنى الآية: وجوه يومئذٍ ناضرة من النَّضارة، وهي الجمال والحُسن، يعني: وجوه يومئذٍ جميلة، فيها نضارة وحُسن، إِلَى رَبِّهَا نَاظِرَةٌ: تنظر إليه، وهي وجوه المؤمنين والمؤمنات.\nقال تعالى: إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ  ۝  عَلَى الْأَرَائِكِ يَنْظُرُونَ [المطففين:22- 23] يعني: ينظرون إلى وجه ربِّهم في دار الكرامة، قال سبحانه: لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ [يونس:26]، جاء عن النبي ﷺ أنه قال: الحسنى: الجنة، والزيادة: النظر إلى وجه الله جلَّ وعلا.\nفالمؤمنون المحسنون يوم القيامة يرون الله جلَّ وعلا في الجنة، كما يرونه في عرصات القيامة، فضلًا منه وإحسانًا جلَّ وعلا، قال تعالى في أهل الجنة: لَهُمْ مَا يَشَاءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ [ق:35]، قال أهلُ العلم: \"إنه النظر إلى وجه الله\".\nوقال النبيُّ ﷺ في الأحاديث الصَّحيحة: إنَّكم ترون ربَّكم يوم القيامة كما ترون القمر ليلة البدر، لا تُضامون في رؤيته، وكما ترون الشمسَ صَحْوًا ليس دونها سحابٌ، هكذا يراه المؤمنون يوم القيامة وفي الجنة، وهكذا المؤمنات؛ لأنَّ الله وعد الجميع النَّعيم المقيم في الجنة، والنظر إلى وجهه .\nوقد أنكر أهلُ البدع من الجهمية والمعتزلة ذلك، وقولهم باطل، مَن أنكر الرؤية يوم القيامة فهو ضالٌّ مُضلٌّ، مخالفٌ لأهل السنة والجماعة، تابع لأهل البدع، فالله جل وعلا بيَّن أن أهل الإيمان يرون ربهم يوم القيامة وفي الجنة، وهكذا النبي ﷺ أخبر في الأحاديث المتواترة الصَّحيحة الثابتة: أن المؤمنين يرون ربهم يوم القيامة في الجنة وفي عرصات القيامة، والوعد بذلك عامٌّ للمؤمنين والمؤمنات جميعًا.\nأما في الدنيا: فلا يراه أحدٌ في الدنيا، يقول النبيُّ ﷺ: واعلموا أنه لن يرى أحدٌ منكم ربَّه حتى يموت، وقد سأل موسى ربَّه أن يراه فقال له ربَّه: إنَّك لن تراني: قَالَ لَنْ تَرَانِي [الأعراف:143]، فالرب  لا يُرى في هذه الدنيا بالعينين، وإنما يُرى في الآخرة.\nأما رؤيته بالقلب -استحضاره بالقلب- فالإنسان يؤمن به، ويستحضر عظمته، وأنه الكامل في ذاته وأسمائه وصفاته وأفعاله، هذا حقٌّ، المؤمنون يؤمنون به، ويعتقدون أنَّه  الكامل في ذاته وأسمائه وصفاته وأفعاله، وأنه المستحقُّ للعبادة جلَّ وعلا.\nوقد يُرى في النوم أيضًا، كما رآه النبيُّ ﷺ في النوم.\nأما بالبصر في اليقظة فلا يُرى إلا يوم القيامة وفي الجنة، يراه المؤمنون والمؤمنات خاصةً، أما الكفار فلا يرونه، قال تعالى: كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ [المطففين:15]، فمن أعظم عذابهم أنهم يُحجبون عن الله يوم القيامة، ولا يرونه .","link":"https://binbaz.org.sa/fatwas/21171/ما-الحق-في-روية-المومنين-والملاىكة-ربهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0967هل الملائكة يرون الله عز وجل؟.mp3","categories":["اليوم الآخر"]},{"id":2550,"question":"من قال: إنها ثلاث نفخات؟","title":"ما الصواب في عدد مرات النفخ في الصور؟","answer":"الجواب: الصواب أنها نفختان، نفخة الفزع هي نفخة الصعق. أما ما في حديث الصور أنها ثلاث؛ فحديث الصور ضعيف، حديث الصور الذي فيه النفخات الثلاث ضعيف، والصواب الذي دل عليه القرآن: نفختان.\nس: الذي في القرآن أنها نفختان؟\nالشيخ: نفختان في الزمر وغيرها، صريحة في الزمر، الأولى: نفخة الصعق، وهي نفخة الفزع التي في سورة النمل، والثانية: نفخة البعث والنشور، نسأل الله حسن الختام، نسأل الله السلامة، اللهم سَلِّم سَلِّم.","link":"https://binbaz.org.sa/fatwas/22681/ما-الصواب-في-عدد-مرات-النفخ-في-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث بين النفختين أربعون فهل هي نفختين أم ثلاث.mp3","categories":["شروح الحديث","اليوم الآخر"]},{"id":2591,"question":"هل ورد في مدة الموقف شيء؟","title":"ما مقدار يوم القيامة والموقف فيه؟","answer":"الجواب: اليوم مقداره خمسون ألف سنة، ولكن مثل ما قال جل وعلا، لا يأتي وسط النهار إلا وقد قضى الله بين الناس: أَصْحَابُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُسْتَقَرًّا وَأَحْسَنُ مَقِيلًا [الفرقان:24] استنبط العلماء من مقيلا أنه يأتي نصف النهار وقد انتهى الأمر، والله المستعان.\nس:بالنسبة لأول الحديث يجمع الله الأولين والآخرين، وفي نهاية الحديث أمتي أمتي؟\nالشيخ: هذا تُرِك القصد المتعلق بالموقف، كما في الرواية الأخرى، صريح في أنه يشفع في أهل الموقف ثم في أمته.","link":"https://binbaz.org.sa/fatwas/22724/ما-مقدار-يوم-القيامة-والموقف-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مدة الموقف في القيامة.mp3","categories":["اليوم الآخر"]},{"id":2593,"question":"هل يُستثنى أناسٌ مِن الذين يبلُغُهم الهم والغم والكرب؟","title":"هل يُستثنى المؤمن مِن الكرب في القيامة؟","answer":"الجواب: الظاهر العموم، الشيء الخفيف، هذا يعم الجمع، لكن الشدة على الكفار فَإِذَا نُقِرَ فِي النَّاقُورِ ۝ فَذَلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ ۝ عَلَى الْكَافِرِينَ غَيْرُ يَسِيرٍ [المدثر:8-10] أما المؤمن خفيف ما يصيبه من ذلك إلا الشيء اليسير.","link":"https://binbaz.org.sa/fatwas/22726/هل-يستثنى-المومن-من-الكرب-في-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يستثنى المؤمن من الذين يبلغهم الهم والغم والكرب في القيامة.mp3","categories":["اليوم الآخر"]},{"id":2615,"question":"مَنْ يتكلّف في تأويل الرؤية هل يَكْفُر؟","title":"حكم تأويل رؤية الله في الجنة","answer":"الجواب: مَن أنكرها كَفَر، من أنكر الرؤية (رؤية الله تعالى في الجنة) كَفَر؛ لأنه مُكَذِّب لله.\nس: وإذا تأوّلها؟\nالشيخ: المقصود: إن كان التأويل معناه إنكارها؛ كفر.","link":"https://binbaz.org.sa/fatwas/22750/حكم-تاويل-روية-الله-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تأويل رؤيا الله في الجنة.mp3","categories":["اليوم الآخر"]},{"id":3145,"question":"هل الجِنُّ المسلمون يدخلون الجنة؟","title":"هل يدخل الجن المسلمون الجنة؟","answer":"الجواب: نعم، هذا هو الصواب: مسلمهم إلى الجنة، وكافرهم إلى النار، مثل الإنس.","link":"https://binbaz.org.sa/fatwas/23307/هل-يدخل-الجن-المسلمون-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل الجن المسلمون الجنة.mp3","categories":["اليوم الآخر"]},{"id":3192,"question":"بالنسبة للمسلمين يوم القيامة هل تُوزن أعمالهم أو تُوزن الأعمالُ والأشخاصُ كذلك؟","title":"هل تُوزن الأعمالُ والأشخاصُ يومَ القيامة؟","answer":"الجواب: يُوزن العمل ويُوزن الشخص، كما قال تعالى: فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا [الكهف:105]. وفي الحديث الرجل السمين العظيم لا يزن عند الله جناح بعوضة.\nس: وكذلك بالنسبة للكفار والمشركين وأهل النفاق الأكبر؟\nالشيخ: ذكر الشيخ تقي الدين رحمه الله أن الكفار لا حساب عليهم بل يُساقون، تُجمع أعمالهم وتُحصى وتُعرض عليهم؛ ليعرفوا سوء عملهم، ثم يُساقون إلى النار، نسأل الله العافية.\nس: كما جاء في قوله تعالى: وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ.. [الفرقان:23].\nالشيخ: فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا [الفرقان: 23].","link":"https://binbaz.org.sa/fatwas/23355/هل-توزن-الاعمال-والاشخاص-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل توزن الأعمال أو توزن الأعمال والأشخاص يوم القيامة.mp3","categories":["اليوم الآخر"]},{"id":3231,"question":"مالك خازنُ جهنم من الملائكة؟","title":"هل خازنُ جهنم من الملائكة؟","answer":"الجواب: نعم وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُمْ مَاكِثُونَ [الزخرف:77].","link":"https://binbaz.org.sa/fatwas/23394/هل-خازن-جهنم-من-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل خازن جهنم من الملائكة.mp3","categories":["اليوم الآخر"]},{"id":3500,"question":"بالنسبة للكفار يرون ربهم في الموقف؟","title":"هل يرى الكفار ربهم في الموقف؟","answer":"الجواب: لا يراه إلا المؤمنون كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ [المطففين: 15]\nس: وحديث: ما منكم من أحد إلا سيكلمه ربه؟\nالشيخ: الكلام غير الرؤية.","link":"https://binbaz.org.sa/fatwas/23679/هل-يرى-الكفار-ربهم-في-الموقف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يرى الكفار ربهم في الموقف.mp3","categories":["اليوم الآخر"]},{"id":3778,"question":"ما ثبت أنها لغة أهل الجنة، العربية؟","title":"هل اللغة العربية لغة أهل الجنة؟","answer":"الجواب: مشهور، ظاهر الحديث أنها لغتهم، لكن ظاهر الأحاديث المروية أنهم يتخاطبون باللغة العربية، ما ورد في الأحاديث الصحيحة أنهم يتخاطبون باللغة العربية.","link":"https://binbaz.org.sa/fatwas/23974/هل-اللغة-العربية-لغة-اهل-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اللغة العربية لغة أهل الجنة.mp3","categories":["اليوم الآخر"]},{"id":4134,"question":"الصراط بعد الجسر أو قبله؟","title":"هل الصراط هو الجسر؟","answer":"الجواب: الصراط هو الجسر المنصوب على متن جهنم، من الأرض إلى فوق، يصعدون إلى الجنة، ومَن سقط سقط في النار -نسأل الله العافية- وهو مثلما قال النبيُّ ﷺ: مدحضةٌ مزلَّةٌ، لكن عليه كلاليب عظيمة، لا يعلم قدر عظمها إلا الله سبحانه وتعالى، تخطف الناس بأعمالهم، والسير ليس على قدر الأبدان والحسّ، لا، إنما هو على حسب الأعمال والقوة المعنوية العملية.","link":"https://binbaz.org.sa/fatwas/24380/هل-الصراط-هو-الجسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الصراط بعد الجسر أو قبله.mp3","categories":["اليوم الآخر"]},{"id":4136,"question":"المنافقون يرون الله في هذا الموقف؟","title":"هل يرى المنافقون ربهم في الموقف يوم القيامة؟","answer":"الجواب: لا، كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ [المطففين:15]، نسأل الله العافية... ما يلزم من بقائهم الرؤيا، يُطفئ الله نورهم ويُساقون إلى النار، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24383/هل-يرى-المنافقون-ربهم-في-الموقف-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يرى المنافقون ربهم في الموقف.mp3","categories":["اليوم الآخر"]},{"id":4137,"question":"الكفرة ما يمرون على الصراط؟","title":"هل يمر الكفار على الصراط؟","answer":"الجواب: لا، ما يمرون، يُساقون إلى النار سوقًا.","link":"https://binbaz.org.sa/fatwas/24384/هل-يمر-الكفار-على-الصراط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمر الكفرة على الصراط.mp3","categories":["اليوم الآخر"]},{"id":4139,"question":"الحوض قبل الجنة أو بعد دخولها؟","title":"هل الحوض قبل الجنة أو بعد دخولها؟","answer":"الجواب: الحوض قبل الجنة، في الموقف يوم القيامة، ولهذا يأتي أناسٌ من الكفرة فيُذادون عنه، لو كان في الجنة ما جاءه إلا المؤمنون، هذا في الموقف يوم القيامة، في العرصات قبل أن يدخل أهلُ الجنة وأهل النار دورهم.","link":"https://binbaz.org.sa/fatwas/24386/هل-الحوض-قبل-الجنة-او-بعد-دخولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحوض قبل الجنة أو بعد دخولها.mp3","categories":["اليوم الآخر"]},{"id":4140,"question":"هل يُذاد عن حوضه أهلُ المعاصي؟","title":"هل العصاة يذادون عن حوض النبي ﷺ؟","answer":"الجواب: لا، الكفار فقط.","link":"https://binbaz.org.sa/fatwas/24387/هل-العصاة-يذادون-عن-حوض-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من هم الذين يذادون عن الحوض.mp3","categories":["اليوم الآخر"]},{"id":4141,"question":"بعد المرور على الصراط الدخول إلى الجنة مباشرةً أو في قنطرةٍ؟","title":"ماذا يكون بعد المرور على الصراط؟","answer":"الجواب: تقدم لكم حديث أبي سعيدٍ... قنطرة قبل دخولهم الجنة، يُحاسب فيها المؤمنون فيما بينهم، ويتقاصُّون فيما بينهم، المؤمنون فقط، فإذا هُذِّبوا ونُقُّوا أُذن لهم في دخول الجنة، تقدَّم هذا الحديث.","link":"https://binbaz.org.sa/fatwas/24388/ماذا-يكون-بعد-المرور-على-الصراط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا بعد المرور على الصراط.mp3","categories":["اليوم الآخر"]},{"id":4204,"question":"قوله \"لم يعمل حسنة قط\" يعني مع التوحيد..؟","title":"معنى ما جاء في الحديث \"لم يعمل حسنة قط..\"","answer":"الجواب: لا بد، هذا غير التوحيد، مثل ما قال :... يخرجون من النار بعدما يشفع الشفعاء، يخرج الله قومًا من النار لم يفعلوا خيرًا قط، يعني إلا التوحيد، يخرجهم الله بغير شفاعة من النار بعدما يمتحشون فيها ويعذبون..... يخرجون من النار، قال في رواية في الصحيح: لم يفعلوا خيرًا قط، وزاد في رواية: إلا أنهم يقولون لا إله إلا الله، وفي رواية: إلا أنهم موحدون.  قد أجمع العلماء قاطبة على أن من مات على الشرك وهو غير معذور ليس من أهل الفترات ولم يعذر، أنه مخلد في النار ولا يخرج منها. وإنما البحث والخلاف بينهم وبين المعتزلة والخوارج في العصاة، فأهل السنة والجماعة يقولون إن العصاة يخرجون ولا يعذبون عذابًا دائمًا أبدًا، بل لهم نهاية، فالعصاة لهم نهاية، وإن وصف بعض عذابهم بالخلود فهو خلود له نهاية، خلود مؤقت مثل خلود الزاني والقاتل وقاتل نفسه، لكن هذا له نهاية. أما خلود الكفار فليس له نهاية، خلودهم مستمر, نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24465/معنى-ما-جاء-في-الحديث-لم-يعمل-حسنة-قط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الخروج من النار، والخلود فيها.mp3","categories":["شروح الحديث","اليوم الآخر"]},{"id":5062,"question":"الصراط لا يمر عليه إلا المؤمنون فقط؟","title":"هل الصراط لا يمر عليه إلا المؤمنون؟","answer":"الجواب: نعم، والكفار يُساقون إلى النار، وبعض مَن يمرُّ عليه يسقط لمعاصيه وسيئاته.","link":"https://binbaz.org.sa/fatwas/29350/هل-الصراط-لا-يمر-عليه-الا-المومنون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الصراط لا يمر عليه إلا المؤمنون؟.mp3","categories":["اليوم الآخر"]},{"id":5483,"question":"هل الكفار يرونه ؟","title":"هل يرى الكفار ربهم عز وجل؟","answer":"الجواب: ما يراه إلا المؤمنون: كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ [المطففين:15]. س: وفي الموقف مَن قال إنهم يرونه من غير جهةٍ؟ ج: هذا غلط، الاتجاه هذا غلط، الاتجاه غلط، غلط في سمعه، ظنَّ أنه مُصيب، غلط، الآية المحكمة: كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ، يكشف الحجاب يوم القيامة حتى يراه المؤمنون في الموقف، وفي بعض الروايات يأتي إليهم، والأمة فيها مُنافقوها، لكن ما يلزم من وجود المنافق أن يرونه، يراه المؤمن، ولا يراه الكافر. س: حديث أبي سعيدٍ: يتصور في غير الصورة التي يعرفونها؟ ج: يعني: المؤمنون، هذا المقصود، يعني: يبدو لهم بالصورة التي يعرفونها؛ حتى يعرفوه، يبدو لهم ما يعرفون دون ما يُشوش عليهم.[1]","link":"https://binbaz.org.sa/fatwas/31382/هل-يرى-الكفار-ربهم-عز-وجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 008.mp3","categories":["اليوم الآخر"]},{"id":5695,"question":"إن والدي دهس طفلًا عمره يقارب السنتين، وسبب الحادث أن لدى والدي السيارة، وكانت واقفة قبل أن يركب سيارته نظر تحتها من جميع الوجوه، ولم ير أحدًا، وركب السيارة، وفي هذه الأثناء قام أحد إخوة الطفل، ووضعه تحت إطار السيارة الأمامي، دون علم والدي، وعندما مشى دهس الطفل، فهل يلزمه صيام شهرين، أم لا؟","title":"حكم من قتل طفلاً بسيارته خطأ","answer":"الجواب: مثل ما جاء في الكفارة، يلزمه صيام شهرين، لو قدر على العتق يعتق بنفسه صاحب السيارة الذي دهس؛ لأنه هو الذي باشر القتل، فعليه الدية، وعليه الكفارة. والكفارة عتق رقبة مؤمنة إن تيسرت، فإن لم يتيسر فعليه صيام شهرين متتابعين، كما بين الله في كتابه العزيز في سورة النساء، وهو الداعس، وهو القاتل؛ لأن ذلك الذي وضعه ما عنده قصد أن يقتل.  أما لو كان مثل ما قال الشيخ، لو كان إنسانًا جاء بآدمي، وطرحه أمام السيارة ليدعسه صاحب السيارة على غفلة يكون هو القاتل، الذي طرحه بين يدي السيارة، لكن هذا طرحه إما لأجل الظل يبغيه في الظل، أو لأسباب أخرى، فنقول: قدر الله موته على هذه السيارة، فالداعس هو الذي عليه الدية والكفارة جميعًا.","link":"https://binbaz.org.sa/fatwas/990/حكم-من-قتل-طفلا-بسيارته-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_19.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":5784,"question":"أحد الإخوة جاءنا بمطبوع فيه أكثر من سبع ورقات، وتكلم فيه بحث مثير أمام رجال الدين والعلم، فيه نهاية العالم ستقع بعد 298 سنة، هذا ما تقوله فواتح السور، وجاء ببعض الأدلة من القرآن على أن العالم سينتهي بعد 298 سنة، ما ندري بنى رأيه على أي شيء، والكتاب كله مع سماحتكم؟","title":"ما حكم تحديد نهاية العالم بوقت معين؟","answer":"الجواب:  هذا طبعًا سمعنا عنه، بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذا الكلام سمعنا عنه من أيام، وهذا الذي قاله هذا القائل خرافة من الخرافات، وجهل من الجهل، ولا ينبغي أن يلتفت إليه، ولا أن يعول عليه، بل ذلك ضلال مبين.  وقد أخبر الله -جل وعلا- في كتابه العظيم، في آيات أن الساعة لا يعلمها إلا هو  ولا يعلم متى تجيء إلا الله -جل وعلا- ولا تأتي إلا بغتة لا يعلمها إلا الله  فلا ينبغي أن يلفت إلى هذا. والله -جل وعلا- قال: إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ [لقمان:34] وذكر بقية الخمس، وقال النبي ﷺ: مفاتح الغيب خمسة منها: علم الساعة، لا يعلمها إلا الله -جل وعلا- ونص القرآن: يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا قُلْ إِنَّمَا عِلْمُهَا عِنْدَ رَبِّي لَا يُجَلِّيهَا لِوَقْتِهَا إِلَّا هُوَ ثَقُلَتْ فِي السَّمَاوَاتِ وَالْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْأَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِنْدَ اللَّهِ [الأعراف:187].  ودلت الآيات الكريمات من القرآن على ذلك، ودلت الأحاديث الصحيحة عن رسول الله على ذلك، وأجمع العلماء على ذلك. وكل استنباط يخالف ما جاءت به السنة، والكتاب فهو استنباط باطل، بل خرافة، بل قول على الله بغير علم، بل هذا القائل يستتاب، فإن تاب وإلا قتل كافرًا، من قال: إن الساعة تكون في يوم كذا، أو بعد يوم كذا، أو في ساعة كذا، أو في سنة كذا، فهذا جهل وضلال، وكفر يستتاب صاحبه، وإن تاب وإلا وجب أن يقتل مرتدًا؛ لأنه مكذب لله ورسوله، الله يقول لا يعلمها إلا الله[1] وهو يقول: أنا أعلمها تأتي في وقت كذا بعد كذا، فهذا لا يقوله إلا مصاب في عقله، ودينه.","link":"https://binbaz.org.sa/fatwas/1109/ما-حكم-تحديد-نهاية-العالم-بوقت-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_115.mp3","categories":["اليوم الآخر"]},{"id":5817,"question":"أطفال الكفار، يموتون مسلمين، أو كفارًا؟","title":"حكم أطفال المشركين","answer":"الجواب: أطفال الكفار مثل ما قال الرسول ﷺ: الله أعلم بما كانوا عاملين حكمهم حكم أهلهم، لا يغسل، ولا يصلى عليه مع أهله، إذا مات بين أهله يدفن مثل أهله، لا يغسل، ولا يصلى عليه؛ لأنه كافر، ولكن يوم القيامة الله أعلم بما كانوا عاملين.  والصحيح: أنهم يمتحنون يوم القيامة، الله يمتحنهم يوم القيامة، ويأمرهم، فإذا أطاعوا؛ دخلوا الجنة، وإن عصوا؛ دخلوا النار مع أهليهم، وكذلك أهل الفترة الذين ماتوا في الفترة، ما جاءتهم رسل في الدنيا، ما جاءهم رسول يوم القيامة، يمتحنون، ويؤمرون، وينهون، فإن أجابوا؛ دخلوا الجنة، وإن عصوا؛ دخلوا النار، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1138/حكم-اطفال-المشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_144.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":6352,"question":"هل الخلائق يرون الله في القيامة؟","title":"حكم رؤية الخلائق لله تعالى يوم القيامة","answer":"الجواب: يراه المؤمنون فقط، لا يراه إلا المؤمنون. السؤال: يقول: يكلمهم، وليس بينه وبينهم ترجمان؟ الجواب: كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ [المطففين:15] يكلمهم، ولكن لا يرونه كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ  ۝  ثُمَّ إِنَّهُمْ لَصَالُوا الْجَحِيمِ [المطففين:15-16] نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1945/حكم-روية-الخلاىق-لله-تعالى-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_732.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":6513,"question":"هل إقامة الحدود تكفر الذنوب مثل: القتل والرجم، والجلد وهكذا؟","title":"الحدود كفارة للذنوب","answer":"الجواب: نعم ثبت عنه ﷺ أنه لما ذكر المعاصي قال: ومن أدركه الله بالدنيا كان كفارة له إذا كان جلد، ولم يعد إلى الزنا؛ صار كفارة له، وإذا زنا، ورجم؛ لأنه محصن، قد تزوج فرجم؛ صار توبة له، والله يمحو به السيئة عنه، فلا يؤخذ بها يوم القيامة، ولا يجمع الله عليه عذابين، عذاب في الدنيا، وعذاب في الآخرة، لكن الزاني الذي جلد، وقام عليه الحد، ثم عاد إلى الزنا يؤخذ بالثاني، لا بالأول، وهكذا كلما عاد عليه ذنب الإعادة، أما الذنب الأول الذي تاب منه، أو أقيم عليه الحد منه هذا لا يؤخذ به. لكن إذا عاد بعد التوبة إلى زنا ثانٍ، أخذ بالثاني، وإذا تاب من الثاني، ثم عاد إلى الثالث؛ أخذ بالثالث، وهكذا الرابع، وهكذا الخامس، كل ذنب يتوب منه؛ لا يؤخذ به، لكن إذا عاد إلى شيء آخر من جديد؛ أخذ بالجديد حتى يتوب، ولا يسمى ناقضًا للأول للتوبة لا، إذا كانت التوبة صادقة، مشتملة على الشروط، ثم وقع في المعصية بعد ذلك، وهو قد تاب توبة صادقة، وفي نيته العزم ألا يعود، ولكن بُلي بالشيطان، وعاد -والعياذ بالله- فهذا يؤخذ بالذنب الأخير؛ حتى يتوب إلى الله منه، وهكذا كلما عاد بعد توبة صادقة؛ أخذ بالأخير، لا بما مضى، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2247/الحدود-كفارة-للذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_868.mp3","categories":["الجنايات والحدود","اليوم الآخر"]},{"id":9775,"question":"هذه رسالة وردت من عبد الرحمن من العراق يقول فيها: قرأت في كتاب الشفاء العليل لـابن القيم رحمه الله يقول: بعد الملايين من السنين من العذاب المقيم في النار يمحو الله النار، ويستند على آيات من القرآن منها قوله تعالى: خَالِدِينَ فِيهَا إِلَّا مَا شَاءَ اللَّهُ [الأنعام:128] وبقوله تعالى: خَالِدِينَ فِيهَا [الأنعام:128] فيقول: الخلود هو الاستقرار مدة معينة من الزمن، ولو كانوا خالدين فيها أبداً لقال تعالى: خالدين فيها أبداً، يقول السائل: ولكن هناك آية واحدة في القرآن في سورة الجن يقول الله تعالى فيها: وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ فَإِنَّ لَهُ نَارَ جَهَنَّمَ خَالِدِينَ فِيهَا أَبَدًا [الجن:23].يقول: فلا أدري أعالم مثل ابن القيم تفوته هذه الآية، وما مدى صحة ما قال بارك الله فيكم؟","title":"الرد على من يقول بفناء النار","answer":"الجواب: هذا القول قول لبعض السلف، يروى عن بعض السلف وعن بعض الصحابة، وذكره ابن القيم وذكره شيخ الإسلام ابن تيمية وذكره آخرون.\nولكنه قول مرجوح عند أهل السنة، قول ضعيف، والصواب الذي عليه أهل السنة والجماعة وهو قول جمهورهم أن النار تبقى أبد الآباد، وأن أهلها يبقون فيها أبد الآباد وهم الكفرة، كما قال جل وعلا: لا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا كَذَلِكَ نَجْزِي كُلَّ كَفُور [فاطر:36] وقال سبحانه في حقهم: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37] يعني: مستمر نسأل الله العافية.\nوقال سبحانه: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167] فالذي عليه أهل السنة والجماعة إلا النادر والقليل، أن عذاب النار مؤبد الآباد مؤبد أبداً ليس لها نهاية، فهم مستمرون فيها باقون فيها أبد الآباد، وهي باقية أبد الآباد.\nوقد رجع ابن القيم إلى هذا وأوضحه في كتاب الوابل الصيب، وقال: إن النار تبقى أبد الآباد، وإنما يخرج منها أهل التوحيد، هم الذين يخرجون منها الذين ماتوا على توحيد الله ولكن لهم معاصي دخلوا بها النار، وهذا حق، فإن أهل السنة والجماعة يقولون: إن العصاة لا يخلدون في النار، من مات على الإسلام ولكنه دخل النار بالمعاصي إما بالزنا وإما بشرب الخمر وإما بالربا وإما بعقوق الوالدين، أو بغير هذا من المعاصي هؤلاء لا يخلدون، الله سبحانه يدخل النار من العصاة من شاء سبحانه من لم يعف عنهم ، ويبقون فيها ما شاء الله، على قدر أعمالهم الخبيثة، فإذا طهروا ونقوا وزال خبثهم أخرجهم الله من النار إلى نهر يقال له: نهر الحياة، فينبتون فيه كما تنبت الحبة في حميل السيل، فإذا تم خلقهم أدخلهم الله الجنة، ويشفع فيهم النبي ﷺ، ويشفع فيهم الملائكة والمؤمنون والأنبياء والأفراط، هذا جاءت به السنة المتواترة عن النبي ﷺ: أن الله يخرج من النار من كان في قلبه مثقال حبة خردل من إيمان وفي اللفظ الآخر: مثقال ذرة من إيمان.\nفأهل التوحيد الذين ماتوا على التوحيد على الإسلام، ولكنهم دخلوا النار بمعاصيهم هؤلاء لا يخلدون، بل يخرجهم الله من النار إلى الجنة، هذا قول أهل الحق من أهل السنة والجماعة، خلافاً للخوارج وخلافاً للمعتزلة ومن كان على شاكلتهم، الذين يقولون: إن العصاة مخلدون في النار، هذا قول باطل، قول الخوارج وقول المعتزلة في تخليد العصاة في النار قول باطل، خلاف ما جاءت به النصوص الكثيرة عن رسول الله عليه الصلاة والسلام، وهي متواترة وثابتة.\nأما الكفار فإنهم يخلدون فيها أبد الآباد، هذا هو الحق الذي عليه جمهور أهل السنة وهو الذي قامت عليه الأدلة الشرعية.\nفينبغي لك أيها السائل! أن تلتزم بهذا، وألا تلتفت إلى غيره، والله ولي التوفيق.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7944/الرد-على-من-يقول-بفناء-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25805.mp3","categories":["اليوم الآخر"]},{"id":12199,"question":"تقول أختنا: هل هناك دليل على أن الرسول ﷺ رأى الله  وهل هناك دليل على رؤية الناس يوم القيامة لله؟","title":"ما الدليل على رؤية النبي لله، ورؤية الناس لله يوم القيامة؟","answer":"الجواب: أما في الدنيا فلم ير ربه ﷺ وقد طلب موسى أن يرى ربه فقال: .. لَن تَرَانِي.. [سورة الأعراف:143]، وقال نبينا محمد ﷺ: واعلموا أنه لن يرى أحدٌ منكم ربه حتى يموت والنبي ﷺ لم ير ربه، سئل عن هذا، سأله أبو ذر، قال يا رسول الله: هل رأيت ربك؟ قال: رأيت نورًا وفي لفظ قال: نورٌ أنى أراه؟ رواه مسلم في الصحيح. وبين لنا أنه لن يرى أحدنا ربه حتى يموت، فعلم بهذا أنه لا يرى في الدنيا  وإنما يرى في الآخرة، قد يرى في النوم كما أخبر به النبي ﷺ لكن لا يرى بالعين في اليقظة إلا في الآخرة. وقد تواترت الأخبار عن الرسول ﷺ أن الله يرى في الآخرة، يراه المؤمنون في القيامة، ويراه أهل الجنة في الجنة، وهذا إجماع أهل السنة والجماعة. وقد أنكر ذلك بعض أهل البدع، وقالوا: إنه لا يرى حتى في الآخرة، وهذا قولٌ باطل، بل من عرف الأحاديث الصحيحة المتواترة؛ عرف أنه حق، أنه يرى في الآخرة، ويرى في الجنة، يراه المؤمنون، وأن من أنكر ذلك؛ فقد كذب النبي ﷺ، والرسول ﷺ أخبرنا ﷺ أننا نرى ربنا، قال في بعض الروايات في الصحيحين ﷺ: إنكم سترون ربكم كما ترون القمر ليلة البدر، لا تضامون في رؤيته، وكما ترون الشمس صحوًا، ليس دونها سحاب فأخبر ﷺ أنه يُرى -جل وعلا- رؤية واضحة ظاهرة، يراه المؤمنون في القيامة، ويراه المؤمنون في الجنة كما يُرى القمر ليلة البدر، لا يضامون في رؤيته، يعني لا يُزحمون في رؤيته، ولا يتضامون أيضًا ولا يشكون في رؤيته  هكذا أخبر ﷺ. وقد جاءت به الأخبار عن رسول الله المتواترة اليقينية عن رسول الله ﷺ وأجمع عليه أهل السنة والجماعة من أصحاب النبي ﷺ وأتباعهم بإحسان، كلهم أجمعوا على أن الله  يرى في الآخرة، ويراه أهل الجنة، يراه المؤمنون، ولا يراه الكافرون، قال تعالى: كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ [سورة المطففين:15]، يعني الكفار، لا يرونه يوم القيامة، محجوبون عنه، وأما المؤمنون فيرونه في القيامة، ويرونه في الجنة كما يشاء  هذا هو قول أهل الحق، وهو قول أهل السنة والجماعة. وقد ذهب جمعٌ من أهل العلم على أن من أنكر ذلك؛ فهو كافر، ذهب جمع من أهل السنة والجماعة على من أنكر رؤية الله في الجنة، وفي القيامة يكون كافرًا، لأنه مكذبٌ للرسول ﷺ فيما صح عنه ﷺ من الأحاديث المتواترة الصحيحة الثابتة عن رسول الله ﷺ. نسأل الله أن يجعلنا وإياكم وسائر المسلمين ممن يراه، وممن يفوز بذلك، في يوم القيامة، وفي دار الكرامة، ونسأل الله العافية من طاعة الهوى والشيطان.","link":"https://binbaz.org.sa/fatwas/10385/ما-الدليل-على-روية-النبي-لله-وروية-الناس-لله-يوم-القيامة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44406.mp3","categories":["اليوم الآخر"]},{"id":13318,"question":"سماحة الشيخ! في بداية هذا اللقاء حدثونا عن شيء عن نعيم الجنة، وعن الطرق الموصلة إليها، نسأل الله أن يجعلنا وإياكم منهم.","title":"نعيم الجنة والطرق الموصلة إليها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الله -جل وعلا- بيّن في كتابه الكريم صفة الجنة، وصفة نعيمها، وصفة أهلها، كما بين سبحانه صفة النار، وأغلالها، وأنواع شرها، وصفات أهلها. فالواجب على كل مكلف أن يحذر صفات أهل النار، وأن يجتهد في التخلق، والاتصاف بصفات أهل الجنة، كما يقول -جل وعلا-: إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ آخِذِينَ مَا آتَاهُمْ رَبُّهُمْ إِنَّهُمْ كَانُوا قَبْلَ ذَلِكَ مُحْسِنِينَ ۝ كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ ۝ وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:15-19] كما يقول سبحانه: إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ ادْخُلُوهَا بِسَلامٍ آمِنِينَ ۝ وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ إِخْوَانًا عَلَى سُرُرٍ مُتَقَابِلِينَ ۝ لا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُمْ مِنْهَا بِمُخْرَجِينَ [الحجر:45-48] ويقول سبحانه: إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ ۝ فَاكِهِينَ بِمَا آتَاهُمْ رَبُّهُم [الطور:17-18]، وقال -جل وعلا- في سورة القلم: إِنَّ لِلْمُتَّقِينَ عِنْدَ رَبِّهِمْ جَنَّاتِ النَّعِيمِ [القلم:34] في آيات كثيرة. فالواجب على المؤمن أن يهتم بهذا الأمر، وأن يعنى بصفات أهل الجنة، وأهم شيء أداء الواجبات، وترك المحارم، فيعتني بأداء فرائض الله، وترك محارم الله، والوقوف عند حدود الله، هذا هو السبب الذي جعله الله موصلاً للجنة بفضله ورحمته  وليحذر كل الحذر من صفات أهل النار الذين بين الله حالهم في كتابه العظيم: إِنَّ الْمُجْرِمِينَ فِي عَذَابِ جَهَنَّمَ خَالِدُونَ ۝ لا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ ۝ وَمَا ظَلَمْنَاهُمْ وَلَكِنْ كَانُوا هُمُ الظَّالِمِينَ ۝ وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُمْ مَاكِثُونَ ۝ لَقَدْ جِئْنَاكُمْ بِالْحَقِّ وَلَكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَارِهُونَ [الزخرف:74-78] هذه حالهم نسأل الله العافية. بينت لهم الحقيقة، ودعوا إلى أسباب السعادة، وبلغتهم الرسل، وأنزل الله عليهم الكتب، ولكنهم تابعوا الهوى والشيطان؛ فندموا غاية الندامة، قال تعالى: وَسِيقَ الَّذِينَ كَفَرُوا إِلَى جَهَنَّمَ زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَتْلُونَ عَلَيْكُمْ آيَاتِ رَبِّكُمْ وَيُنْذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَذَا قَالُوا بَلَى وَلَكِنْ حَقَّتْ كَلِمَةُ الْعَذَابِ عَلَى الْكَافِرِينَ ۝ قِيلَ ادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ ۝ وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ [الزمر:71-73] هذه حال هؤلاء وحال هؤلاء.  فجدير بالمؤمن، وجدير بالمؤمنة العناية بأخلاق المؤمنين، والاتصاف بصفاتهم العظيمة: من توحيد الله، والإخلاص له، والمحافظة على الصلاة، وأداء الزكاة، وصوم رمضان، وحج البيت.. الاجتهاد في كل خير.. بر الوالدين.. صلة الرحم.. الإكثار من ذكر الله.. الأمر بالمعروف.. النهي عن المنكر.. إلى غير هذا من وجوه الخير. ثم الحذر من جميع ما نهى الله عنه، وأعظمها الشرك، أعظم ما نهى الله عنه الشرك الأكبر، قال -جل وعلا-: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72] وقال تعالى: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] قال تعالى: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ ۝ بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ [الزمر:65-66] وقال في صفات أوليائه المؤمنين، صفات عباد الرحمن: وَعِبَادُ الرَّحْمَنِ الَّذِينَ يَمْشُونَ عَلَى الأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلامًا [الفرقان:63] هذه صفات عباد الرحمن وَعِبَادُ الرَّحْمَنِ الَّذِينَ يَمْشُونَ عَلَى الأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلامًا [الفرقان:63] هذه من صفاتهم العظيمة. فينبغي للمؤمن أن يتصف بصفات أولياء الله، وليحذر من صفات أعداء الله أينما كان، وعباد الرحمن هم المتقون، هم أولياء الله، هم المحسنون هم الذين أطاعوا الله ورسوله، واستقاموا على دينه وَعِبَادُ الرَّحْمَنِ الَّذِينَ يَمْشُونَ عَلَى الأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلامًا [الفرقان:63]. ويقول سبحانه في صفة عباده المتقين: إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ ۝ فَاكِهِينَ بِمَا آتَاهُمْ رَبُّهُمْ وَوَقَاهُمْ رَبُّهُمْ عَذَابَ الْجَحِيمِ ۝ كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا كُنتُمْ تَعْمَلُونَ ۝ مُتَّكِئِينَ عَلَى سُرُرٍ مَصْفُوفَةٍ وَزَوَّجْنَاهُمْ بِحُورٍ عِينٍ ۝ وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَا أَلَتْنَاهُمْ مِنْ عَمَلِهِمْ مِنْ شَيْءٍ كُلُّ امْرِئٍ بِمَا كَسَبَ رَهِينٌ ۝ وَأَمْدَدْنَاهُمْ بِفَاكِهَةٍ وَلَحْمٍ مِمَّا يَشْتَهُونَ ۝ يَتَنَازَعُونَ فِيهَا كَأْسًا لا لَغْوٌ فِيهَا وَلا تَأْثِيمٌ ۝ وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَكْنُونٌ ۝ وَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ يَتَسَاءَلُونَ ۝ قَالُوا إِنَّا كُنَّا قَبْلُ فِي أَهْلِنَا مُشْفِقِينَ ۝ فَمَنَّ اللَّهُ عَلَيْنَا وَوَقَانَا عَذَابَ السَّمُومِ ۝ إِنَّا كُنَّا مِنْ قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ [الطور:17-28]. فأنت يا عبدالله الآن في دار المهلة، في دار العمل، وهكذا أنت يا أمة الله في دار المهلة، في دار العمل، فالواجب على كل منكما تقوى الله  وذلك بتوحيده، والإخلاص له في جميع الأعمال؛ الصلاة.. الصوم.. الصدقة.. الاستغفار.. الذكر.. الإنسان، هكذا يتوجه بقلبه إلى الله، ويخلص عمله لله، إن تصدق لله.. إن صلى لله.. إن صام فلله.. إلى غير ذلك كله لله كما قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ [البينة:5] ويقول سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3] ويقول -جل وعلا- في كتابه الكريم: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14].  ومن أهم المهمات أيضًا الحذر من جميع المعاصي.. من الزنا.. السرقة.. الغش للمسلمين.. الكذب.. الربا.. العقوق للوالدين، أو أحدهما.. قطيعة الرحم.. الغيبة.. النميمة.. إلى غير هذا مما حرم الله، الإنسان يحاسب نفسه في أداء فرائض الله، والإكثار من طاعة الله، ويحاسب نفسه في الحذر من محارم الله ومعاصيه، يرجو ثوابه ويخشى عقابه . نسأل الله أن يوفقنا، وجميع المسلمين لكل ما يرضيه، وأن يعيذنا وجميع المسلمين من أسباب غضبه، وأسباب نقمته، إنه -جل وعلا- جواد كريم. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ على هذا التوجيه المبارك.","link":"https://binbaz.org.sa/fatwas/11604/نعيم-الجنة-والطرق-الموصلة-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54101.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":13396,"question":"هذا السؤال أيضًا يقترب من السؤال السابق، ويقول فيه السائل الذي لم يذكر الاسم في هذه الرسالة: سماحة الشيخ! السلام عليكم ورحمة الله وبركاته، وسؤالي: إذا توفي الشخص، وهذا الشخص محافظ على أداء الصلوات، وعلى الصيام، وعلى صيام التطوع في بعض الأحيان، يومي الإثنين والخميس، مع صيام ستة أيام من شوال، وحج إلى بيت الله الحرام، ولم يشرك بالله، وموحد لله، مع قراءة القرآن في بعض الأحيان، يقول: لكن هذا الإنسان لا يضمن نفسه من النميمة، ومن الصغائر، السؤال يبقى: هل هذا الشخص إذا مات هل يعذب على هذه الذنوب؟ وجهونا في ضوء هذا السؤال.","title":"هل يعذب المؤمن إذا مات على معصية؟","answer":"الجواب: الله -جل وعلا- وعد المؤمنين بالجنة، والكرامة، وتوعد العصاة بالعقوبات، والنميمة، من أقبح السيئات، النميمة من أقبح السيئات، يقول النبي ﷺ: لا يدخل الجنة نمام فهو على خطر إذا مات على النميمة، أو الغيبة، أو الزنا، أو الخمر، لكنه تحت مشيئة الله، يقول الله -جل وعلا- في كتابه العظيم: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]. فإذا مات على أعمال صالحة، وتقوى لله، ولكن عنده ذنوب وسيئات؛ فهو أمره إلى الله -جل وعلا- إن كانت صغائر؛ غفرها الله بأعماله الصالحة، أما إن كان فيها كبائر، كالنميمة وأشباهها؛ فهو تحت مشيئة الله؛ لأن الله يقول -جل وعلا=: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31] ويقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن إذا اجتنب الكبائر. فإذا كان ما اجتنبها؛ ما تكون هذه الصلوات كفارة، فإذا كان عنده الزنا مصر عليه، أو الخمر مصر عليه؛ ما يكفر بالصلاة ونحوها، يبقى عليه خطره، وهو تحت المشيئة. وهكذا إذا مات على عقوق الوالدين، قطيعة الرحم، الربا، وما أشبه ذلك من الكبائر -نسأل الله العافية- يكون تحت مشيئة الله على خطر، قد يدخل النار، ويعذب على قدر المعاصي التي مات عليها من الكبائر، وقد يعفو الله عنه بأسباب كثيرة من أعمال صالحة، من شفاعة بعض الشفعاء من المؤمنين.. إلى غير ذلك. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11687/هل-يعذب-المومن-اذا-مات-على-معصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52515.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":13448,"question":"في سؤاله الثاني يقول هذا السائل من الأردن: نسمع أن الإنسان ينادى باسم أمه يوم القيامة بحيث يقال له: يا فلان ابن فلانة، هل هذا صحيح سماحة الشيخ؟","title":"هل ينادى الإنسان باسم أمه يوم القيامة؟","answer":"الجواب: ليس بصحيح، الناس يدعون بآبائهم يوم القيامة، يدعون بأسماء آبائهم، لا بأمهاتهم، هذا من كلام العامة الباطل، الناس يوم القيامة يدعون بأسمائهم وأسماء آبائهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11747/هل-ينادى-الانسان-باسم-امه-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52717.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":13620,"question":"يقول في سؤاله الثاني: كم عدد النفخات يوم القيامة؟ وهل بعد القيام من القبور يشاهد الناس أهوال القيامة من تفجير بحار، وتطاير نجوم، أم يكون ذلك في النفخة الأولى نفخة الصعق؟","title":"عدد النفخات في الصور","answer":"الجواب: النفخات، الصواب: أنه نفختان، كما دل عليها القرآن: نفخة الفزع، وهي الصعق. والثانية: نفخة البعث، ...نفخة الصعق هذه فيها تنشق السماء، وتنفطر السماء، وتطوى السموات.. إلى غير ذلك، وتزلزل الجبال .. تنسف الجبال.. إلى غير ذلك، ويموت الناس. والثانية يبعث الناس من قبورهم، ومن البحار، ومن كل مكان، ويجتمعون بين يدي الله -جل وعلا- من كل مكان، من سائر أرجاء الأرض، يجمعهم الله في صعيد واحد، يسمعهم الكلام، وينفذهم البصر، ويقضي بينهم بحكمه العدل، ويعطون صحفهم، هذا بيمينه، وهذا بشماله، وتوزن أعمالهم، هذا يرجح ميزانه، وهذا يخف ميزانه، كل هذا بعد البعث والنشور، أما الأولى؛ فهي الموت، يقال لها: نفخة الصعق، ونفخة الفزع، إذا مدها جبرائيل[1] كل من سمعها يموت، هذا يبيع ويشتري ويموت وهو في مكانه، وهذا يلوط حوض إبله، يموت في مكانه، وهذا يأكل يموت في مكانه واللقمة في يده، وهكذا، كل يموت في مكانه الذي يسمع الصيحة فيه، وهي صيحة عظيمة يمدها إسرافيل. وجاء في حديث ضعيف أنها ثلاث: نفخة الفزع يفزع الناس، ثم الصعق يموتون، ثم الثالثة يبعثون لكن الحديث ضعيف، الثابت في القرآن، وفي الأحاديث الصحيحة نفختان: إحداهما تسمى نفخة الصعق، وهي الفزع يموت الناس بها. والثانية: نفخة البعث، والنشور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11971/عدد-النفخات-في-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53405.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":13627,"question":"يقول في سؤاله الثاني: كم عدد النفخات يوم القيامة؟ وهل بعد القيام من القبور يشاهد الناس أهوال القيامة من تفجير بحار، وتطاير نجوم، أم يكون ذلك في النفخة الأولى نفخة الصعق؟","title":"عدد النفخات في الصور","answer":"الجواب: النفخات، الصواب: أنه نفختان، كما دل عليها القرآن: نفخة الفزع، وهي الصعق. والثانية: نفخة البعث، ...نفخة الصعق هذه فيها تنشق السماء، وتنفطر السماء، وتطوى السموات.. إلى غير ذلك، وتزلزل الجبال .. تنسف الجبال.. إلى غير ذلك، ويموت الناس. والثانية يبعث الناس من قبورهم، ومن البحار، ومن كل مكان، ويجتمعون بين يدي الله -جل وعلا- من كل مكان، من سائر أرجاء الأرض، يجمعهم الله في صعيد واحد، يسمعهم الكلام، وينفذهم البصر، ويقضي بينهم بحكمه العدل، ويعطون صحفهم، هذا بيمينه، وهذا بشماله، وتوزن أعمالهم، هذا يرجح ميزانه، وهذا يخف ميزانه، كل هذا بعد البعث والنشور، أما الأولى؛ فهي الموت، يقال لها: نفخة الصعق، ونفخة الفزع، إذا مدها جبرائيل[1] كل من سمعها يموت، هذا يبيع ويشتري ويموت وهو في مكانه، وهذا يلوط حوض إبله، يموت في مكانه، وهذا يأكل يموت في مكانه واللقمة في يده، وهكذا، كل يموت في مكانه الذي يسمع الصيحة فيه، وهي صيحة عظيمة يمدها إسرافيل. وجاء في حديث ضعيف أنها ثلاث: نفخة الفزع يفزع الناس، ثم الصعق يموتون، ثم الثالثة يبعثون لكن الحديث ضعيف، الثابت في القرآن، وفي الأحاديث الصحيحة نفختان: إحداهما تسمى نفخة الصعق، وهي الفزع يموت الناس بها. والثانية: نفخة البعث، والنشور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11971/عدد-النفخات-في-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53405.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":13868,"question":"يقول في سؤاله الثاني: ما هو الصراط المنصوب على متن جهنم؟ وما حكم الإيمان به؟ وهل كل من مر به أصابه أذى أم لا؟ جزاكم الله خيرًا.","title":"ما هو الصراط المنصوب على متن جهنم؟","answer":"الجواب: هذا صراط ينصبه الله للمؤمنين، يمر عليه المؤمنون إلى الجنة، عليه كلاليب تخطف الناس بأعمالهم، فمن مر عليه نجا، وقد يخطف بعض الناس فيسقط بذنوبه، وقد يخطف وينجو ويسير، فهو صراط عظيم ثابت بينه النبي ﷺ يمر عليه الذين كتب الله لهم الجنة، وقد يسقط بعض الناس لبعض ذنوبه، ويعذب على قدر معصيته، لا يمر عليه إلا المؤمنون، أما الكفار لا، لا يمرون على الصراط، إنما هذا لأهل الجنة، فمن مر عليه نجا ومن سقط بذنوبه فيعذب على قدرها، وأما الكفار فيساقون إلى النار، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12259/ما-هو-الصراط-المنصوب-على-متن-جهنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53805.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":14381,"question":"يقول في سؤاله الثاني: هل يوجد كتاب لابن تيمية -رحمه الله- يقول فيه: بأن الجنة والنار لا خلود فيهن؟","title":"هل قال ابن تيمية بأن الجنة والنار لا خلود فيهما؟","answer":"الجواب: ابن تيمية وغيره من السلف كلهم يقولون: إنّ أهل الكفر مخلدون في النار، وأهل الإيمان مخلدون في الجنة، هذا بإجماع أهل السنة والجماعة: أن أهل الجنة مخلدون أبد الآباد، لا موت فيها ولا فناء، بل هي دائمة، وأهلها دائمون. وذهب بعض السلف إلى أن النار لها نهاية، وأنها بعد مضي الأحقاب لابِثِينَ فِيهَا أَحْقَابًا [النبأ:23] لها نهاية تفنى، ولكنه قول ضعيف ساقط مردود، والذي عليه جمهور أهل السنة والجماعة أن النار باقية ومستمرة لا تفنى أبدًا، وأهلها كذلك من الكفرة معذبون فيها دائمًا، نسأل الله العافية، كما قال الله -جل وعلا- في كتابه العظيم في سورة البقرة: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167] وقال : يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37] قال تعالى: لابِثِينَ فِيهَا أَحْقَابًا [النبأ:23]  إلى أن قال: فَذُوقُوا فَلَنْ نَزِيدَكُمْ إِلَّا عَذَابًا[النبأ:30] يعني: أحقاب، كلما مضى أحقاب جاء بعدها أحقاب.\nوقال تعالى: كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا [الإسراء:97] فهي مستمرة -نسأل الله العافية-، وأهلها كذلك مقيمون فيها أبدًا، وهم الكفار. أما العصاة فلهم أمد، عصاة الموحدين لهم أمد إذا دخلوها يخرجون منها بعدما يطهرون، العصاة منهم من يعفى عنه، ولا يدخلها، ومنهم من يدخلها، وإذا طهر أخرجه الله منها، وصار إلى الجنة، ولا يبقى في النار ويخلد فيها أبد الآباد إلا الكفار الذين ماتوا على الكفر بالله، نسأل الله العافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12862/هل-قال-ابن-تيمية-بان-الجنة-والنار-لا-خلود-فيهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55204.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":14579,"question":"ذكر العلامة ابن القيم في عدد من كتبه من بينها: حادي الأرواح، والصواعق المرسلة بأن النار تفنى، وقال -رحمه الله- بفناء النار، وذكر عددًا من الأدلة على ذلك، القول الصحيح سماحة الشيخ في ذلك.","title":"صحة القول بفناء النار عن ابن القيم","answer":"الجواب: الذي أعلم أن ابن القيم وشيخ الإسلام إنما ينقلان أقوال الناس نقل، ولا يختاران ذلك، إنما ينقلان أقوال من قال بفناء النار، والذي عليه أهل السنة والجماعة أنها باقية ودائمة، والقول بفنائها قول باطل، قول ضعيف، لا وجه له، ولا يعول عليه، بل هي باقية دائمة كالجنة، الجنة باقية دائمة بإجماع أهل السنة والجماعة، وهكذا النار عند أهل السنة والجماعة إلا من شذ، ولا عبرة بالشاذين. النار دائمة باقية، وأهلها مخلدون فيها من الكفرة لا تفنى ولا تبيد، بل هم مقيمون فيها أبد الآباد: لابِثِينَ فِيهَا أَحْقَابًا [النبأ:23] يعني: أحقابًا بعد أحقاب لا يخرجون منها أبدًا، قال الله -جل وعلا-: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167] نص القرآن، قال تعالى في سورة المائدة: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37] عذابهم مقيم فيها لا يظعنون منها، نسأل الله العافية. أما العاصي فقد يعذب فيها بعصيانه، ثم يخرج، لا يخلد فيها إلا الكفار، أما من دخلها من العصاة من الزناة أو شراب المسكر أو العاقين لوالديهم أو ما أشبه ذلك من العصاة قد يدخلون النار، لكن لا يخلدون، يعذبون فيها ما شاء الله ثم يخرجهم الله من النار.  أما الكفار فإنهم يخلدون فيها أبد الآباد، ولا يخرجون منها أبدًا، وقال تعالى في حقهم: فَذُوقُوا فَلَنْ نَزِيدَكُمْ إِلَّا عَذَابًا [النبأ:30] وقال في حقهم: كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا [الإسراء:97] نسأل الله العافية، فهذا كله يدل على أنها مستمرة باقية أبد الآباد كالجنة، والقول بفنائها قول شاذ لا يعول عليه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13076/صحة-القول-بفناء-النار-عن-ابن-القيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55705.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":14619,"question":"السائلة التي رمزت لاسمها بـ (م. ع. ع) المنطقة الشرقية، تسأل هذا السؤال وتقول: يقولون: بأن من مات وهو صغير -أي: بمعنى مولود- يكون من حور الجنة، هل هذا القول صحيح؟","title":"هل من مات صغيرًا من حور الجنة؟","answer":"الجواب: لا، ليس بصحيح، حور الجنة نساء خلقن في الجنة وللجنة، أما هو يكون من أهل الجنة، الطفل شفيعاً لوالديه إذا كانا مسلمين، ويكون من أهل الجنة، من جنس بني آدم، مثلما يحصل لبني آدم وغيره، له من أهل الجنة يتنعم في الجنة، وله من الحور، هم من أبناء الدنيا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13112/هل-من-مات-صغيرا-من-حور-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55908.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":14996,"question":"هذا سائل للبرنامج يقول: من هم الذين يدخلون الجنة بغير حساب؟ هل الذين هم لا يرقون ولا يسترقون يدخلون الجنة؟ أرجو التوضيح في ذلك، مأجورين.","title":"من هم الذين يدخلون الجنة بغير حساب؟","answer":"الجواب: من استقام على دينه، وأدى ما فرض الله عليه، وترك ما حرم الله عليه، دخل بغير حساب ولا عذاب، ومنهم السبعون ألفًا الذين لا يسترقون، ولا يكتوون، ولا يتطيرون، وعلى ربهم يتوكلون، تركوا الطيرة؛ لأنها محرمة، وتركوا الكي والاسترقاء استحبابًا؛ لأن الرسول ﷺ ذكر أنها من صفات السبعين ألفًا، فإذا ترك الكي واستعمل دواءً آخر فلا بأس.  النبي -عليه الصلاة والسلام- قال: الشفاء في ثلاث: كية نار، وشرطة محجم، وشربة عسل، وما أحب أن أكتوي وقد كوى بعض أصحابه، فإذا ترك الكي فهذا أفضل، إذا تيسر دواء آخر، وإلا فلا بأس بالكي، ولا يمنعه ذلك من كونه من السبعين؛ لأن السبعين ألفًا هم الذين استقاموا على دين الله، وتركوا محارم الله، وأدوا ما أوجب الله. ومن صفاتهم الطيبة: عدم الاسترقاء، ولكن الاسترقاء لا يمنع من كونه من السبعين، والاسترقاء طلب الرقية، وإذا دعت الحاجة إلى هذا فلا بأس، النبي ﷺ أمر عائشة أن تسترقي، وأمر أم أولاد جعفر أن تسترقي لأولادها، فلا حرج في ذلك، وإذا دعت الحاجة إلى الكي فلا بأس أن يكتوي، كما قال ﷺ: الشفاء في ثلاث: كية نار، وشرطة محجم، وشربة عسل يدل على أن الكي لا بأس به، لكن تركه أفضل إذا تيسر غيره، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/13495/من-هم-الذين-يدخلون-الجنة-بغير-حساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/%D8%B5%D9%81%D8%A7%D8%AA%20%D8%A7%D9%84%D8%B0%D9%8A%D9%86%20%D9%8A%D8%AF%D8%AE%D9%84%D9%88%D9%86%20%D8%A7%D9%84%D8%AC%D9%86%D8%A9%20%D8%A8%D8%BA%D9%8A%D8%B1%20%D8%AD%D8%B3%D8%A7%D8%A8%20%D9%88%D9%84%D8%A7%20%D8%B9%D8%B0%D8%A7%D8%A8.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":16609,"question":"هل الرجل وزوجته يجتمعون في الجنة إذا كانوا من أهل الخير؟","title":"هل يجتمع الرجل وزوجته في الجنة؟","answer":"الجواب: الله أعلم، هذا إلى الله -جل وعلا- لكن جاء في بعض الأحاديث فيها ضعف أنه إذا كان لها أزواج أنها تخير، وتختار أحسنهم خلقًا، لكن هذا ليس بمقطوع به؛ لأن الأحاديث فيها ضعف، والله -جل وعلا- هو الذي يعلم  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15344/هل-يجتمع-الرجل-وزوجته-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75814.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":17238,"question":"المستمع: هداب الهداب من الرياض، يقول: هل يدخل المؤمنون من الجن الجنة مع الإنس؟ وأين تكون منازلهم في الجنة؟ وهل يلتقون مع الإنس أيضًا في الجنة، سماحة الشيخ؟","title":"أين مصير مؤمني الجن في الآخرة؟","answer":"الجواب: الكفار من الجن والإنس في النار، والمؤمنون من الجن والإنس في الجنة، الكفار من الجن والإنس في النار، والمؤمنون من الجن والإنس في الجنة، قال الله تعالى في سورة الرحمن: وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ [الرحمن:46] يعني: من الجن والإنس فَبِأَيِّ آلاءِ رَبِّكُمَا تُكَذِّبَانِ [الرحمن:47].. وقال -جل وعلا- فيها في سورة الرحمن: هَذِهِ جَهَنَّمُ الَّتِي يُكَذِّبُ بِهَا الْمُجْرِمُونَ ۝ يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ [الرحمن:43-44]. فالجن والإنس سوا سوا، من آمن منهم ومات على الإيمان؛ دخل الجنة، ومن مات على الكفر؛ دخل النار، سواءً جني، أو إنسي. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16068/اين-مصير-مومني-الجن-في-الاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59115.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":18067,"question":"رسالة وصلت إلى البرنامج من العراق وباعثها أحد الإخوة من هناك يقول: (ط. ع. ب) أخونا بدأ رسالته بقوله:من المعروف أن معنى المادة هو كل شيء يشغل حيزًا من الفراغ وله كتلة، وتوجد بثلاث حالات وهي: الحالة الصلبة، والحالة السائلة، والحالة الغازية، ومن المعروف أيضًا وعلى ما أعتقد أن هناك صورتين للوجود فقط، وهي: الصورة المادية، والصورة الروحانية أي: الروح.وهذا العالم عالم الدنيا الذي نعيش فيه هو عالم مادي ملموس؛ لأن كل شيء فيه يرى ويلمس أو تتحسس به كالهواء مثلاً، والسؤال هو: هل عالم الآخرة عالم مادي أم عالم روحاني أم غير ذلك؟ جزاكم الله خيرًا.","title":"هل عالم الآخرة عالم مادي؟","answer":"الجواب: العالم الأخروي عالم مادي لكننا لم نصل إليه الآن، وإنما نصل إليه بعد البعث والنشور، ولكنا علمناه بالأدلة القاطعة التي لا ريب فيها ولا شك فيها من طريق الرسل عليهم الصلاة والسلام، ومن طريق الفطرة التي فطر الله عليها الناس، ومن طريق ما جاءت به الرسل من الكتب وأعظمها وأرفعها شأنًا القرآن الكريم. وقد تواترت الأدلة النقلية والعقلية التي فطر الله عليها العباد على الإيمان بالآخرة والجنة والنار وأنها حق، وأنها كائنة، وأن أهل الجنة ينعمون بنعم محسوسة، يأكلون ويشربون، ويتمتعون بالزوجات من الحور العين وغيرهن، ويتمتعون بما هناك من أنواع النعيم، كما أن أهل النار يتألمون بما أعد الله لهم من العذاب ويذوقون مسه وشره وبلاءه، كل هذا أمر معلوم مقطوع بالأدلة القطعية التي لا ريب فيها ولاشك، ومن كذبها فهو كافر حلال الدم والمال، مأواه النار وبئس المصير، نعوذ بالله من ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17102/هل-عالم-الاخرة-عالم-مادي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90202.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":18256,"question":"سماحة الشيخ هذا السائل أحمد إبراهيم من الرياض يقول: كيف يقوم الناس من قبورهم يوم القيامة؟","title":"كيفية قيام الناس من قبورهم يوم القيامة","answer":"الجواب: أخبر الله عنهم بما بيَّن : يَوْمَ يَخْرُجُونَ مِنَ الأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَى نُصُبٍ يُوفِضُونَ[المعارج:43] فهم يخرجون من الأجداث إذا سمعوا الصيحة، وهي نفخة البعث النفخة الثانية يخرجهم الله من قبورهم ومن كل مكان، ويجمعهم جل وعلا يوم القيامة، والله أعلم بكيفية ذلك  المقصود أنهم يخرجون حفاة عراة غرلًا كما جاءت به الأحاديث، حفاة لا نعال عليهم، عراة لا لباس عليهم، غرلًا غير مختونين حتى يقضى بينهم، وأول من يكسى إبراهيم كمـا أخبر به النبي عليه الصلاة والسلام. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17305/كيفية-قيام-الناس-من-قبورهم-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78312.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":18719,"question":"يقول: بعد موت كل الخلائق، ومنهم الملائكة، وبقاء المولى  كيف حال بني آدم في هذه اللحظة؟ وهل هم ينعمون ويعذبون؟","title":"حال بني آدم بعد فناء الملائكة وبقاء الخالق سبحانه","answer":"الجواب: الله أعلم، هذا إلى الله -جل وعلا- إذا قامت القيامة خرج الناس من قبورهم، ثم يصيرون إلى ما يستحقون، هذا يصير إلى النار، وهذا يصير إلى الجنة على حسب أعمالهم.  أما حال خروجهم فهم في خوف شديد، يوم عظيم شديد الأهوال، لكن الله يسهله على المؤمن، وهو عسير على الكافرين.  أما تفصيله فإلى الله  لكنه يوم عظيم، يوم عسير، يوم شديد الأهوال، لكن الله يسهله على المؤمن -جل وعلا- قال -جل وعلا-: فَإِذَا نُقِرَ فِي النَّاقُورِ ۝ فَذَلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ ۝ عَلَى الْكَافِرِينَ غَيْرُ يَسِيرٍ[المدثر:8-10] لكن المؤمن يسهل الله عليه كل شيء بسبب إيمانه وتقواه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17843/حال-بني-ادم-بعد-فناء-الملاىكة-وبقاء-الخالق-سبحانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78904.mp3","categories":["الرقائق","اليوم الآخر"]},{"id":19689,"question":"نختم هذا اللقاء بهذا السؤال سماحة الشيخ، يقول السائل: ما هي اللغة التي يتكلم بها الله  يوم القيامة لعباده وضحوا لنا ذلك مأجورين؟","title":"اللغة التي يتكلم بها الله جل جلاله يوم القيامة","answer":"الجواب: ظاهر النصوص أنها اللغة العربية، ظاهر النصوص الواردة عن النبي ﷺ أنه يكلم الناس باللغة العربية، والله أعلم جل وعلا، ظاهر النصوص الواردة في كلامه جل وعلا باللغة العربية ولا أعلم مانعًا من أنه يتكلم بغيرها، وهو على كل شيء قدير  يعلم كل شيء، ويعلم جميع اللغات، ولا تخفى عليه خافية جل وعلا، لكن ظاهر النصوص أنه يخاطب الناس يوم القيامة باللغة العربية، وأن لغة أهل الجنة هي اللغة العربية، يتخاطبون بهذه اللغة المعروفة أهل الجنة، والله يخاطبهم بذلك كما هو ظاهر النصوص، وهو سبحانه يعلم كل شيء، ويقدر على كل شيء، وعلى جميع اللغات  ويعلم أحوال أهلها، ويجازيهم على أعمالهم بما يستحقون .","link":"https://binbaz.org.sa/fatwas/18983/اللغة-التي-يتكلم-بها-الله-جل-جلاله-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95043.mp3","categories":["الرقائق","اليوم الآخر"]}]
